import React, { useState } from 'react';
import { NumberPicker } from '@alifd/next';

export default function Demo() {
  const [max, setMax] = useState(13);
  const [value, setValue] = useState(10);

  return (
    <div>
      <div>max: {max}</div>
      <button onClick={() => setMax(max + 1)}>max + 1</button>
      <br /><br />
      <NumberPicker
        value={value}
        max={max}
        onChange={setValue}
      />
      <span style={{ color: 'red', marginLeft: 16 }}>
        点击 max 增加后最大值没有实时的更新到组件中
      </span>
    </div>
  );
}
